	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void inlineDeadlineExpirationDoesNotAcquireWriterOwnerMonitor(@TempDir Path directory) throws Exception {
		SchedulingStore store = new SchedulingStore(directory);
		store.init();
		CountDownLatch timerEntered = new CountDownLatch(1);
		CountDownLatch releaseTimer = new CountDownLatch(1);
		CountDownLatch promotionEntered = new CountDownLatch(1);
		CountDownLatch releasePromotion = new CountDownLatch(1);
		CountDownLatch coordinatorEntered = new CountDownLatch(1);
		CountDownLatch releaseCoordinator = new CountDownLatch(1);
		AtomicReference<Thread> expiryThread = new AtomicReference<>();
		AtomicBoolean abortPromotion = new AtomicBoolean();
		store.beforePromotion.set(owner -> {
			promotionEntered.countDown();
			await(releasePromotion);
			if (abortPromotion.get()) {
				throw new CancellationException(
						"release the test's owner-monitor gate after a failed expiry assertion");
			}
		});
		store.beforeDeadline.set(deadline -> {
			if (Thread.currentThread() == expiryThread.get()) {
				coordinatorEntered.countDown();
				await(releaseCoordinator);
			}
		});
		try (var executor = Executors.newScheduledThreadPool(3);
				QueryExecutionDeadline timerGate = QueryExecutionDeadline.start(1_000);
				var timerRegistration = timerGate.onExpiration(() -> {
					timerEntered.countDown();
					await(releaseTimer);
				})) {
			assertTrue(timerEntered.await(3, TimeUnit.SECONDS));
			// Hold the actual deadline Timer so expiration must be published inline by admission's check.
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1_000)) {
				Future<?> promoting = executor.submit(() -> {
					try (var scope = deadline.enter();
							var unexpected = store.getBackingStore()
									.getExplicitSailSource()
									.beginPublication(new Object())) {
						throw new AssertionError("an expired publisher acquired native authority");
					}
				});
				try {
					assertTrue(promotionEntered.await(3, TimeUnit.SECONDS));
					Future<?> expiring = executor.submit(() -> {
						expiryThread.set(Thread.currentThread());
						try (var scope = deadline.enter();
								var unexpected = store.getBackingStore()
										.registerReadAttempt(new Object(),
												(kind, token, grace, attempts, views) -> false)) {
							throw new AssertionError("expired read-attempt admission succeeded");
						}
					});
					try {
						assertTrue(coordinatorEntered.await(3, TimeUnit.SECONDS));
						CountDownLatch deadlineReached = new CountDownLatch(1);
						executor.schedule(deadlineReached::countDown,
								Math.max(0, deadline.deadlineNanos() - System.nanoTime()), TimeUnit.NANOSECONDS);
						assertTrue(deadlineReached.await(3, TimeUnit.SECONDS));
						releaseCoordinator.countDown();
						ExecutionException failure = assertThrows(ExecutionException.class,
								() -> expiring.get(2, TimeUnit.SECONDS),
								"inline expiration under the coordinator must finish while promotion holds the owner monitor");
						assertTrue(failure.getCause() instanceof QueryInterruptedException,
								failure.toString() + " cause=" + failure.getCause());
					} finally {
						abortPromotion.set(true);
						releaseCoordinator.countDown();
						releasePromotion.countDown();
						try {
							expiring.get(3, TimeUnit.SECONDS);
						} catch (ExecutionException expected) {
							assertTrue(expected.getCause() instanceof QueryInterruptedException);
						}
					}
				} finally {
					abortPromotion.set(true);
					releasePromotion.countDown();
					releaseCoordinator.countDown();
					try {
						promoting.get(3, TimeUnit.SECONDS);
					} catch (ExecutionException expected) {
						assertTrue(expected.getCause() instanceof CancellationException
								|| expected.getCause() instanceof QueryInterruptedException);
					}
				}
			}
		} finally {
			releaseTimer.countDown();
			store.beforePromotion.set(null);
			store.beforeDeadline.set(null);
			store.shutDown();
		}
	}

	private static ThreadInfo awaitPromotionOrOwnerExclusion(AtomicReference<Thread> follower,
			CountDownLatch promotion) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(3);
		while (System.nanoTime() < deadline) {
			Thread thread = follower.get();
			ThreadInfo info = thread == null ? null
					: ManagementFactory.getThreadMXBean().getThreadInfo(thread.threadId(), 30);
			if (info != null && (promotion.getCount() == 0 || info.getThreadState() == Thread.State.BLOCKED)) {
				return info;
			}
			Thread.onSpinWait();
		}
		throw new AssertionError("the follower must reach promotion or the predecessor's owner exclusion");
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(10, TimeUnit.SECONDS), "test scheduling gate was not released");
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

	private static final class SchedulingStore extends LmdbStore {
		private final AtomicReference<Consumer<Object>> beforeRelease = new AtomicReference<>();
		private final AtomicReference<Consumer<Object>> beforePromotion = new AtomicReference<>();
		private final AtomicReference<Consumer<QueryExecutionDeadline>> beforeDeadline = new AtomicReference<>();

		private SchedulingStore(Path directory) {
			super(directory.toFile(), new LmdbStoreConfig().setForceSync(false));
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchBasedJoinEstimatorEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchBasedJoinEstimatorEnabled,
					ValueStore::new, TripleStore::new) {
				@Override
				void beforeWriterAuthorityRelease(Object owner) {
					Consumer<Object> callback = beforeRelease.get();
					if (callback != null) {
						callback.accept(owner);
					}
				}

				@Override
				void beforeWriterAuthorityPromotion(Object owner) {
					Consumer<Object> callback = beforePromotion.get();
					if (callback != null) {
						callback.accept(owner);
					}
				}

				@Override
				void beforeGrowthAdmissionDeadlineCheck(QueryExecutionDeadline deadline) {
					Consumer<QueryExecutionDeadline> callback = beforeDeadline.get();
					if (callback != null) {
						callback.accept(deadline);
					}
				}
			};
		}
	}
